insert into change_headers (id, ts) values (73, '2026-11-09') on duplicate key update ts = values(ts);
insert into change_descriptions (id, lang, description) values (73, 'ru', 'Калькуляторами теперь можно пользоваться прямо из ChatGPT, Claude и других ИИ-ассистентов: спросите своими словами, а ассистент сам посчитает стоимость построек, время полёта, производство и многое другое. Как подключить, рассказано на новой странице: ссылка на неё есть в меню, в разделе «ИИ-ассистенты», и на главной.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (73, 'en', 'The calculators can now be used right from ChatGPT, Claude and other AI assistants: ask in your own words, and the assistant works out building costs, flight times, production and much more for you. How to connect is explained on a new page: it is linked from the menu, under "AI assistants", and from the start page.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (73, 'pt', 'Agora pode usar as calculadoras diretamente no ChatGPT, no Claude e noutros assistentes de IA: pergunte por palavras suas e o assistente calcula o custo dos edifícios, o tempo de voo, a produção e muito mais. A forma de ligar está explicada numa nova página: encontra a ligação no menu, na secção «Assistentes de IA», e na página inicial.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (73, 'de', 'Die Rechner lassen sich jetzt direkt aus ChatGPT, Claude und anderen KI-Assistenten nutzen: Frag einfach mit eigenen Worten, und der Assistent berechnet Gebäudekosten, Flugzeiten, Produktion und vieles mehr. Wie man ihn verbindet, steht auf einer neuen Seite: Der Link dazu ist im Menü unter „KI-Assistenten“ und auf der Startseite.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (73, 'pl', 'Z kalkulatorów można teraz korzystać bezpośrednio w ChatGPT, Claude i innych asystentach AI: zapytaj własnymi słowami, a asystent sam policzy koszt budynków, czas lotu, produkcję i wiele więcej. Jak go podłączyć, wyjaśnia nowa strona: link do niej jest w menu, w sekcji „Asystenci AI”, oraz na stronie głównej.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (73, 'es', 'Ahora puedes usar las calculadoras directamente desde ChatGPT, Claude y otros asistentes de IA: pregunta con tus propias palabras y el asistente calculará el coste de los edificios, el tiempo de vuelo, la producción y mucho más. Cómo conectarlo se explica en una nueva página: el enlace está en el menú, en la sección «Asistentes de IA», y en la página de inicio.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (73, 'fr', 'Les calculateurs s''utilisent désormais directement depuis ChatGPT, Claude et d''autres assistants IA : posez votre question avec vos propres mots, et l''assistant calcule le coût des bâtiments, la durée de vol, la production et bien plus encore. La marche à suivre pour le connecter est expliquée sur une nouvelle page, accessible depuis le menu, rubrique « Assistants IA », et depuis la page d''accueil.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (73, 'it', 'Ora i calcolatori si possono usare direttamente da ChatGPT, Claude e altri assistenti IA: chiedi con parole tue e l''assistente calcola il costo degli edifici, il tempo di volo, la produzione e molto altro. Come collegarlo è spiegato in una nuova pagina: il link si trova nel menu, nella sezione «Assistenti IA», e nella pagina iniziale.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (73, 'nl', 'De calculators zijn nu rechtstreeks te gebruiken vanuit ChatGPT, Claude en andere AI-assistenten: stel je vraag in je eigen woorden, en de assistent rekent gebouwkosten, vluchttijden, productie en nog veel meer voor je uit. Hoe je hem koppelt, staat op een nieuwe pagina: de link vind je in het menu, onder "AI-assistenten", en op de startpagina.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (73, 'sk', 'Kalkulačky teraz môžete používať priamo z ChatGPT, Claude a ďalších AI asistentov: opýtajte sa vlastnými slovami a asistent sám vypočíta cenu budov, čas letu, produkciu a oveľa viac. Ako ho pripojiť, vysvetľuje nová stránka: odkaz na ňu nájdete v menu v sekcii „AI asistenti“ a na úvodnej stránke.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (73, 'tr', 'Hesaplayıcılar artık doğrudan ChatGPT, Claude ve diğer yapay zekâ asistanlarından kullanılabiliyor: sorunuzu kendi sözlerinizle sorun, asistan bina maliyetlerini, uçuş sürelerini, üretimi ve çok daha fazlasını sizin için hesaplasın. Nasıl bağlanacağı yeni bir sayfada anlatılıyor: bağlantısı menüdeki "Yapay zekâ asistanları" bölümünde ve ana sayfada.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (73, 'bs', 'Kalkulatore sada možete koristiti direktno iz ChatGPT-a, Claudea i drugih AI asistenata: pitajte svojim riječima, a asistent će sam izračunati cijenu zgrada, vrijeme leta, proizvodnju i još mnogo toga. Kako ga povezati, objašnjeno je na novoj stranici: link do nje nalazi se u meniju, u odjeljku „AI asistenti“, i na početnoj stranici.') on duplicate key update description = values(description);
